from contextlib import asynccontextmanager
from typing import Annotated

from fastapi import Depends, FastAPI, HTTPException
from sqlmodel import Session

from app.db import get_session, init_db
from app.models import (
    Item,
    ItemCreate,
    ItemRead,
    Order,
    OrderCreate,
    OrderLine,
    OrderLineRead,
    OrderRead,
)


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(lifespan=lifespan)
SessionDep = Annotated[Session, Depends(get_session)]


@app.post("/items", response_model=ItemRead)
def create_item(item: ItemCreate, session: SessionDep) -> Item:
    db_item = Item.model_validate(item)
    session.add(db_item)
    session.commit()
    session.refresh(db_item)
    return db_item


def _order_read(order: Order) -> OrderRead:
    lines = [OrderLineRead.model_validate(line, from_attributes=True) for line in order.lines]
    return OrderRead(
        id=order.id,
        customer_email=order.customer_email,
        lines=lines,
        total_cents=sum(ln.unit_price_cents * ln.quantity for ln in lines),
    )


@app.post("/orders", response_model=OrderRead, status_code=201)
def create_order(order: OrderCreate, session: SessionDep) -> OrderRead:
    db_order = Order(customer_email=order.customer_email)
    for line in order.lines:
        item = session.get(Item, line.item_id)
        if item is None:
            raise HTTPException(status_code=422, detail=f"Item {line.item_id} not found")
        db_order.lines.append(
            OrderLine(item_id=item.id, quantity=line.quantity, unit_price_cents=item.price_cents)
        )
    session.add(db_order)
    session.commit()
    session.refresh(db_order)
    return _order_read(db_order)


@app.get("/orders/{order_id}", response_model=OrderRead)
def read_order(order_id: int, session: SessionDep) -> OrderRead:
    order = session.get(Order, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return _order_read(order)

